package com.vandorlabs.neoforge.legacylanding;

import com.vandorlabs.neoforge.gear.*;
import com.vandorlabs.neoforge.transfer.*;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;

/** Typed idle wheeled-root replacement. The common engine owns durability, never conversion semantics. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs")
public final class NativeLegacyMigration {
 private static final int TILE_BYTES=2*1024*1024;
 private static final NativeTransferSnapshot.Limits LIMITS=new NativeTransferSnapshot.Limits(566,TILE_BYTES,16*1024*1024,32*1024*1024);
 private static final Set<String> OWN=Set.of("id","x","y","z","Progress","ExtensionPixels","GearSize","RedstoneMode","RedstoneChannel","RedstoneChannels","LastSignal","GearHasOwner","GearOwnerDistance","GearOwnerX","GearOwnerZ","NativeLegacyLandingSchema","NativeLegacyLandingIdentity","NativeLegacyLandingRevision","NativeLegacyProxyUpgrade");
 private static void require(boolean value,String why){if(!value)throw new IllegalArgumentException(why);}
 private static boolean pristine(CompoundTag tag){for(String key:tag.getAllKeys())if(!OWN.contains(key)&&!(Set.of("components","NeoForgeData","ForgeCaps","neoforge:attachments").contains(key)&&tag.contains(key,Tag.TAG_COMPOUND)&&tag.getCompound(key).isEmpty())&&!(key.equals("keepPacked")&&tag.contains(key,Tag.TAG_BYTE)&&tag.getByte(key)==0))return false;return true;}
 private static NativeRawCell at(List<NativeRawCell> cells,BlockPos pos){return cells.stream().filter(c->c.pos.equals(pos)).findFirst().orElseThrow(()->new IllegalArgumentException("Missing legacy root before-image"));}
 private static NativeGearLegacyDestination.Column column(NativeCellTransactions.Header header,List<NativeRawCell> before){var source=at(before,header.root());require(source.state.getBlock()==NativeLegacyLandingBindings.BLOCKS.get(NativeLegacyLandingKind.WHEEL)&&!source.state.getValue(NativeLegacyLandingBlock.LOWER)&&source.hasTile(),"Migration needs the permanent wheeled root");var raw=source.tile();require(pristine(raw),"Opaque legacy ownership remains in its original family");var saved=NativeLegacyLandingData.read(raw);require(!saved.legacy()&&!saved.owned()&&header.owner().equals(saved.identity()),"Migration root identity changed");var settings=saved.configuration();float endpoint=source.state.getValue(NativeLegacyLandingBlock.EXTENDED)?settings.pixels()/16F:0;require(Math.abs(saved.progress()-endpoint)<.0001,"Wait for the exact telescopic endpoint");boolean large=settings.size()>=3,deployed=source.state.getValue(NativeLegacyLandingBlock.EXTENDED)&&settings.pixels()>0;var facing=source.state.getValue(NativeLegacyLandingBlock.FACING);var root=header.root();if(large)root=switch(facing){case EAST->root.east();case SOUTH->root.east().south();case WEST->root.south();default->root;};return new NativeGearLegacyDestination.Column(root,facing,large,Math.max(1,(settings.pixels()+15)/16),deployed,settings.mode(),settings.channels(),saved.identity());}
 private record Recipe(NativeGearLegacyDestination.Column column,List<BlockPos> cells,Set<BlockPos> legacy){}
 private static final NativeCellTransactions.MaintenanceFamily<Recipe> FAMILY=new NativeCellTransactions.MaintenanceFamily<>(){
  public ResourceLocation id(){return ResourceLocation.parse("vandorlabs:legacy_wheeled_landing");}public NativeTransferSnapshot.Limits limits(){return LIMITS;}
  public Recipe readRecipe(HolderLookup.Provider registries,NativeCellTransactions.Header header,NativeTransferSnapshot before,NativeTransferSnapshot after,Set<BlockPos> held,CompoundTag raw){require(raw.getAllKeys().equals(Set.of("Schema"))&&raw.contains("Schema",Tag.TAG_INT)&&raw.getInt("Schema")==1,"Unknown legacy migration recipe");var positions=new HashSet<BlockPos>();for(var cell:before.cells())positions.add(cell.pos);require(held.equals(positions),"Migration authority exceeds exact cell coverage");var result=column(header,before.cells());var legacy=new HashSet<BlockPos>();for(var cell:before.cells())if(cell.state.getBlock() instanceof NativeLegacyLandingBlock){require(cell.state.getBlock()==NativeLegacyLandingBindings.BLOCKS.get(NativeLegacyLandingKind.WHEEL)&&cell.hasTile()&&pristine(cell.tile()),"Unrecognized legacy migration source");require(Math.abs((long)cell.pos.getX()-header.root().getX())<=1&&Math.abs((long)cell.pos.getZ()-header.root().getZ())<=1&&cell.pos.getY()<=header.root().getY()&&header.root().getY()-cell.pos.getY()<=5,"Legacy source outside54-cell closure");legacy.add(cell.pos);var data=NativeLegacyLandingData.read(cell.tile());require(header.owner().equals(data.identity())&&(cell.pos.equals(header.root())?!data.owned():data.owned()&&cell.state.getValue(NativeLegacyLandingBlock.LOWER)&&cell.pos.offset(data.ownerX(),data.ownerY(),data.ownerZ()).equals(header.root())),"Legacy helper belongs to another owner");}var source=at(before.cells(),header.root());var own=NativeLegacyLandingData.read(source.tile());for(var offset:com.vandorlabs.gear.core.LegacyLandingLayout.reserved(Math.max(own.progress(),source.state.getValue(NativeLegacyLandingBlock.EXTENDED)?own.configuration().pixels()/16F:0),own.configuration().size()))require(legacy.contains(header.root().offset(offset.x,offset.y,offset.z)),"Incomplete saved legacy reservation");var gear=NativeGearLegacyDestination.validate(registries,result,before.cells(),after.cells());for(int i=0;i<before.cells().size();i++){var a=before.cells().get(i);var b=after.cells().get(i);if(!gear.contains(a.pos))require(legacy.contains(a.pos)&&b.state.isAir()&&!b.hasTile(),"Extra mutation outside typed legacy retirement");}return new Recipe(result,positions.stream().sorted().toList(),Set.copyOf(legacy));}
  public void authorizeMaintenance(ServerLevel world,NativeCellTransactions.Header header,Recipe recipe){var column=recipe.column;require(NativeLegacyLandingBlock.loaded(world,header.root())&&world.getBlockEntity(header.root()) instanceof NativeLegacyLandingEntity,"Legacy root unavailable");var root=(NativeLegacyLandingEntity)world.getBlockEntity(header.root());require(root.current()&&root.physicalRoot()&&root.kind()==NativeLegacyLandingKind.WHEEL&&root.identity().equals(header.owner())&&root.pristine(),"Legacy physical ownership changed");var c=root.settings();require(c.mode()==column.trigger()&&c.channels().equals(column.channels())&&(c.size()>=3)==column.large()&&Math.max(1,(c.pixels()+15)/16)==column.height()&&Math.abs(root.progress()-root.targetDistance())<.0001&&((root.extended()&&c.pixels()>0)==column.deployed()),"Legacy endpoint/input changed");var current=new HashSet<BlockPos>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int depth=0;depth<=5;depth++){var pos=header.root().offset(x,-depth,z);require(NativeLegacyLandingBlock.loaded(world,pos),"Load complete legacy ownership closure");var tile=world.getBlockEntity(pos);if(tile==root||tile instanceof NativeLegacyLandingEntity helper&&root.ownHelper(helper))current.add(pos);}require(current.equals(recipe.legacy),"Legacy ownership closure changed");for(var mount:new TreeSet<BlockPos>(List.of(header.root().above(),column.rootPos().above())))require(NativeLegacyLandingBlock.loaded(world,mount)&&world.getBlockState(mount).isFaceSturdy(world,mount,Direction.DOWN),"Complete the source and modular mounting supports");}
  public boolean additionalMatches(ServerLevel world,NativeCellTransactions.Header header,boolean rollback,Recipe recipe){if(rollback)return true;var mount=recipe.column.rootPos().above();return NativeLegacyLandingBlock.loaded(world,mount)&&world.getBlockState(mount).isFaceSturdy(world,mount,Direction.DOWN);}
  public BlockEntity stage(ServerLevel world,NativeCellTransactions.Header header,NativeRawCell cell,Recipe recipe){return cell.stage(world,tile->tile instanceof NativeLegacyLandingEntity old&&!old.inert()||tile instanceof NativeGearEntity gear&&!gear.inert(),NativeLegacyMigration::same);}
  public boolean same(CompoundTag a,CompoundTag b){return NativeLegacyMigration.same(a,b);}
  public void publish(ServerLevel world,NativeCellTransactions.Header header,NativeRawCell before,NativeRawCell after,BlockEntity staged,NativeTransferHolds.Lease lease,Recipe recipe){NativeGearComponents.withoutBreak(()->NativeLegacyFootprints.withoutCleanup(world,header.root(),()->{try(var scope=lease.allowOnce(after.pos)){if(world.getBlockState(after.pos)!=after.state&&!world.setBlock(after.pos,after.state,Block.UPDATE_KNOWN_SHAPE))throw new IllegalStateException("Legacy conversion cell refused");}if(after.hasTile()){world.removeBlockEntity(after.pos);world.setBlockEntity(staged);staged.setChanged();}else if(world.getBlockEntity(after.pos)!=null)world.removeBlockEntity(after.pos);world.getChunkAt(after.pos).setUnsaved(true);}));if(fault!=null&&Boolean.getBoolean("vandorlabs.legacyMigrationChecks"))fault.accept(header,after);}
  public void released(ServerLevel world,NativeCellTransactions.Header header,boolean rollback,String error,Recipe recipe){var gears=Collections.newSetFromMap(new IdentityHashMap<NativeGearEntity,Boolean>());var legacy=Collections.newSetFromMap(new IdentityHashMap<NativeLegacyLandingEntity,Boolean>());for(var pos:recipe.cells){if(!NativeLegacyLandingBlock.loaded(world,pos))continue;var tile=world.getBlockEntity(pos);if(tile instanceof NativeLegacyLandingEntity old){var root=old.physical();if(root!=null)legacy.add(root);}else if(tile instanceof NativeGearEntity gear){var root=gear.controllerEntity();if(root!=null)gears.add(root);}var state=world.getBlockState(pos);world.sendBlockUpdated(pos,state,state,Block.UPDATE_CLIENTS);world.updateNeighborsAt(pos,state.getBlock());}for(var root:legacy)NativeLegacyUpdates.queue(root);for(var root:gears)root.requestRebuild();var pending=PENDING.get(world);if(pending!=null){var result=pending.remove(header.owner());if(pending.isEmpty())PENDING.remove(world);if(result!=null&&result.requester!=null){var player=world.getServer().getPlayerList().getPlayer(result.requester);if(player!=null){String message=rollback?"Landing gear conversion rolled back. "+error:"Stationary landing gear conversion complete at "+recipe.column.rootPos().toShortString()+".";player.sendSystemMessage(net.minecraft.network.chat.Component.literal(message));}}}}

 };
 static java.util.function.BiConsumer<NativeCellTransactions.Header,NativeRawCell> fault;
 private static final class Pending {
  final NativeCellTransactions.Operation<?> operation;
  UUID requester;
  Pending(NativeCellTransactions.Operation<?> operation){this.operation=operation;}
 }
 private static final Map<ServerLevel,Map<UUID,Pending>> PENDING=new IdentityHashMap<>();
 static NativeCellTransactions.Operation<?> pending(NativeLegacyLandingEntity root) {
  var pending=PENDING.get(root.getLevel());
  var request=pending==null?null:pending.get(root.identity());
  return request==null?null:request.operation;
 }
 static void notifyOnCompletion(NativeLegacyLandingEntity root,net.minecraft.server.level.ServerPlayer requester) {
  var pending=PENDING.get(root.getLevel());
  var request=pending==null?null:pending.get(root.identity());
  if(request!=null)request.requester=requester.getUUID();
 }
 @net.neoforged.bus.api.SubscribeEvent(priority=net.neoforged.bus.api.EventPriority.HIGHEST) public static void register(net.neoforged.neoforge.event.server.ServerStartingEvent event){if(NativeLegacyLandingBindings.enabled())NativeCellTransactions.registerMaintenance(FAMILY);}
 public static NativeCellTransactions.Operation<?> request(NativeLegacyLandingEntity root){require(root.getLevel() instanceof ServerLevel&&root.current()&&root.physicalRoot()&&root.kind()==NativeLegacyLandingKind.WHEEL,"Legacy migration owner unavailable");var world=(ServerLevel)root.getLevel();var existing=PENDING.computeIfAbsent(world,w->new HashMap<>()).get(root.identity());if(existing!=null)return existing.operation;require(root.pristine(),"Opaque legacy ownership remains untouched");var source=capture(world,root.getBlockPos());var header=new NativeCellTransactions.Header(UUID.randomUUID(),FAMILY.id(),root.getBlockPos(),root.identity(),NativeCellTransactions.MAINTENANCE_ACTOR,false);var input=column(header,List.of(source));var owned=new TreeSet<BlockPos>();for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)for(int depth=0;depth<=5;depth++){var pos=root.getBlockPos().offset(x,-depth,z);require(NativeLegacyLandingBlock.loaded(world,pos),"Load every legacy source cell");var tile=world.getBlockEntity(pos);if(tile==root||tile instanceof NativeLegacyLandingEntity helper&&root.ownHelper(helper)){require(tile==root||((NativeLegacyLandingEntity)tile).pristine(),"Opaque helper retained");owned.add(pos);}}var targets=NativeGearLegacyDestination.prepare(world,List.of(input));var afterMap=new HashMap<BlockPos,NativeRawCell>();for(var cell:targets){require(owned.contains(cell.pos)||world.getBlockState(cell.pos).isAir()&&world.getBlockEntity(cell.pos)==null||world.getBlockEntity(cell.pos) instanceof NativeGearEntity,"Clear the complete modular destination");afterMap.put(cell.pos,cell);}var positions=new TreeSet<BlockPos>(owned);positions.addAll(afterMap.keySet());var before=new ArrayList<NativeRawCell>();var after=new ArrayList<NativeRawCell>();for(var pos:positions){before.add(capture(world,pos));after.add(afterMap.getOrDefault(pos,new NativeRawCell(pos,Blocks.AIR.defaultBlockState(),null,TILE_BYTES)));}var raw=new CompoundTag();raw.putInt("Schema",1);var request=new NativeCellTransactions.Request(root.getBlockPos(),root.identity(),new NativeTransferSnapshot(before,LIMITS),new NativeTransferSnapshot(after,LIMITS),positions,raw);var op=NativeCellTransactions.submitMaintenance(world,FAMILY,request);if(op!=null)PENDING.get(world).put(root.identity(),new Pending(op));return op;}
 private static NativeRawCell capture(ServerLevel world,BlockPos pos){require(NativeLegacyLandingBlock.loaded(world,pos),"Load every migration cell");var tile=world.getBlockEntity(pos);return new NativeRawCell(pos,world.getBlockState(pos),tile==null?null:tile.saveWithFullMetadata(world.registryAccess()),TILE_BYTES);}
 private static boolean same(CompoundTag expected,CompoundTag actual){if(Objects.equals(expected,actual))return true;if(expected==null||actual==null)return false;var a=expected.copy();var b=actual.copy();for(var tag:List.of(a,b)){if(tag.contains("keepPacked",Tag.TAG_BYTE)&&tag.getByte("keepPacked")==0)tag.remove("keepPacked");if(tag.contains("NeoForgeData",Tag.TAG_COMPOUND)&&tag.getCompound("NeoForgeData").isEmpty())tag.remove("NeoForgeData");}return a.equals(b);}
 @net.neoforged.bus.api.SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload event){if(event.getLevel() instanceof ServerLevel world)PENDING.remove(world);}
 private NativeLegacyMigration(){}
}
